-- post: dressing-for-riyadh-summer (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40026, now(), now(), 'seed', 'dressing-for-riyadh-summer', 'POST', 0, true, '65f023632bc46470c104b76f', 'PUBLISHED', now() - interval '3 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -490003, "categoryIds": [-451, -452], "tags": ["صيف", "كتان", "summer"], "authorName": "نورة القحطاني", "featured": true}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400051, now(), now(), 'seed', '<p>الجميع ينصح باللون الفاتح، وقليلون ينتبهون إلى أن نسيجًا داكنًا فضفاضًا من الكتان أبرد من قميص أبيض ضيق من البوليستر.</p><h2>النسيج أولًا</h2><p>في المناخ الجاف يبرّد العرق الجسم بالتبخر، وهو ما يحتاج نسيجًا ينفذ منه الهواء. الكتان والقطن المُمشَّط يفعلان ذلك؛ البوليستر يحبس البخار على الجلد.</p><h2>القَصّة ثانيًا</h2><p>المساحة بين القماش والجلد هي ما يسمح للهواء بالحركة. قميص واسع قليلًا أبرد فعليًا من آخر ملتصق، مهما تشابه اللون.</p><h2>الطبقات في الأماكن المكيَّفة</h2><p>الفارق بين الخارج والداخل في الرياض يتجاوز عشرين درجة. طبقة قطنية خفيفة تُخلع عند الدخول أذكى من مواجهة الفارق بقطعة واحدة.</p><h2>ثلاث قطع تكفي الموسم</h2><ul><li>قميص كتان بأكمام طويلة — يحمي من الشمس ويسمح بالهواء</li><li>بنطال قطني واسع من الأسفل</li><li>ثوب أو فستان بقَصّة مستقيمة لا تلتصق بالجسم</li></ul>', 'الملابس في صيف الرياض: النسيج قبل القَصّة', 'الملابس في صيف الرياض: النسيج قبل القَصّة', 'لماذا يتفوق الكتان والقطن المُمشَّط على البوليستر في المناخ الجاف، وكيف تختار القَصّة.', 'صيف, كتان, summer', 'الملابس في صيف الرياض | المجلة', 'dressing-for-riyadh-summer-ar', 'ar', -40026, 'TRANSLATED', 'خمسون درجة وجفاف شديد. اللون الفاتح ليس الحل، بل النسيج الذي يسمح بمرور الهواء.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400052, now(), now(), 'seed', '<p>Everyone recommends pale colours, and few notice that a loose dark linen shirt is cooler than a tight white polyester one.</p><h2>Fabric first</h2><p>In dry heat, sweat cools you by evaporating, which needs a weave air can pass through. Linen and combed cotton do that; polyester traps vapour against the skin.</p><h2>Cut second</h2><p>The gap between cloth and skin is what lets air move. A slightly loose shirt is genuinely cooler than a fitted one, whatever the colour.</p><h2>Layers, because of air conditioning</h2><p>The gap between outdoors and indoors in Riyadh runs past twenty degrees. A light cotton layer you take off on the way in beats meeting both with one garment.</p><h2>Three pieces that carry a season</h2><ul><li>A long-sleeved linen shirt — sun cover and airflow at once</li><li>Cotton trousers cut wide at the hem</li><li>A thobe or dress with a straight line that does not cling</li></ul>', 'Dressing for a Riyadh summer: fabric before cut', 'Dressing for a Riyadh summer: fabric before cut', 'Why linen and combed cotton beat polyester in dry heat, and how to choose a cut that helps.', 'صيف, كتان, summer', 'Dressing for a Riyadh summer | The Magazine', 'dressing-for-riyadh-summer', 'en', -40026, 'TRANSLATED', 'Fifty degrees and very dry air. Pale colour is not the answer — weave that lets air through is.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-4001, -490003, 'CONTENT', '-40026', 'الملابس في صيف الرياض: النسيج قبل القَصّة', -40026, 'POST', 'hero')
on conflict (id) do nothing;

-- post: reading-a-fabric-label (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40027, now(), now(), 'seed', 'reading-a-fabric-label', 'POST', 1, true, '65f023632bc46470c104b76f', 'PUBLISHED', now() - interval '10 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -490004, "categoryIds": [-452], "tags": ["أقمشة", "قطن", "fabric"], "authorName": "سارة الدوسري", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400053, now(), now(), 'seed', '<h2>الوزن بالغرام للمتر</h2><p>قميص قطني بوزن 120 غرامًا شفاف ويفقد شكله بعد عشر غسلات. عند 180 غرامًا يبقى معتدلًا. عند 220 يصلح لفصل أبرد.</p><h2>الممشَّط مقابل العادي</h2><p>التمشيط يزيل الألياف القصيرة قبل الغزل، فيقل الوبر ويزيد النعومة. الفارق في السعر بسيط والفارق في العمر كبير.</p><h2>المزج ليس عيبًا دائمًا</h2><ul><li>2 إلى 5% إيلاستين في القطن يحافظ على شكل الركبة والمرفق</li><li>أكثر من 15% بوليستر في قميص صيفي يعني حرارة محتبسة</li><li>الفيسكوز يسقط بجمال لكنه يضعف وهو مبلول — لا تعصره</li></ul><h2>ما لا تذكره البطاقة</h2><p>كثافة الحياكة وثبات اللون لا يظهران في أي رقم. الاختبار الوحيد هو الغسل الخامس.</p>', 'كيف تقرأ بطاقة القماش', 'كيف تقرأ بطاقة القماش', 'الوزن بالغرام، الغزل المُمشَّط، ونسب المزج: ما تعنيه أرقام بطاقة القماش فعلًا.', 'أقمشة, قطن, fabric', 'كيف تقرأ بطاقة القماش | المجلة', 'reading-a-fabric-label-ar', 'ar', -40027, 'TRANSLATED', '« 100% قطن » لا تكفي. الوزن ونوع الغزل يفرّقان بين قميص يدوم موسمًا وآخر يدوم خمسة.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400054, now(), now(), 'seed', '<h2>Grams per square metre</h2><p>A 120 gsm cotton shirt is see-through and loses its shape after ten washes. At 180 gsm it holds. At 220 it belongs to a cooler season.</p><h2>Combed versus carded</h2><p>Combing strips out short fibres before spinning, which means less pilling and a smoother hand. The price difference is small; the lifespan difference is not.</p><h2>Blends are not automatically a compromise</h2><ul><li>2–5% elastane in cotton keeps knees and elbows from bagging</li><li>More than 15% polyester in a summer shirt means trapped heat</li><li>Viscose drapes beautifully but is weak when wet — never wring it</li></ul><h2>What the label leaves out</h2><p>Knit density and colourfastness appear in no number. The only test is the fifth wash.</p>', 'How to read a fabric label', 'How to read a fabric label', 'Grams per square metre, combed yarn and blend ratios: what the numbers on a label actually mean.', 'أقمشة, قطن, fabric', 'How to read a fabric label | The Magazine', 'reading-a-fabric-label', 'en', -40027, 'TRANSLATED', '“100% cotton” tells you almost nothing. Weight and yarn type separate a shirt that lasts a season from one that lasts five.', null, null, null)
on conflict (description_id) do nothing;
