-- post: inside-the-alterations-room (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40028, now(), now(), 'seed', 'inside-the-alterations-room', 'POST', 2, true, '65f023632bc46470c104b76f', 'PUBLISHED', now() - interval '19 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -490005, "categoryIds": [-453], "tags": ["تعديل", "خياطة", "atelier"], "authorName": "نورة القحطاني", "featured": false}')
