INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400055, now(), now(), 'seed', '<p>خلف المعرض في العليا غرفة بثلاث ماكينات، يعمل فيها خياطان يعدّلان نحو أربعين قطعة كل أسبوع.</p><h2>التعديل الأكثر طلبًا</h2><p>ليس تقصير البنطال، بل تضييق الكتف. معظم القمصان تُقاس على كتف أعرض من المتوسط هنا، والفارق سنتيمتر ونصف يغيّر شكل القطعة كلها.</p><h2>لماذا مجانًا</h2><p>لأن القطعة المعدَّلة لا تُسترجع، ولأن من يرتدي قطعة تناسبه فعلًا يعود. الحساب بسيط.</p><h2>ما لا يمكن تعديله</h2><ul><li>توسيع كتف ضيق — القماش غير موجود</li><li>تغيير مكان الجيوب دون أثر ظاهر</li><li>الجاكيتات المبطنة، إلا بتكلفة تتجاوز قيمتها</li></ul><h2>ثلاثة أيام</h2><p>المدة القياسية ثلاثة أيام. القطع المستعجلة قبل مناسبة تُنجز في يوم واحد إن أمكن، دون رسوم إضافية.</p>', 'داخل غرفة التعديل', 'داخل غرفة التعديل', 'جولة في غرفة التعديل بمعرض العليا، وأكثر التعديلات طلبًا ولماذا.', 'تعديل, خياطة, atelier', 'داخل غرفة التعديل | المجلة', 'inside-the-alterations-room-ar', 'ar', -40028, 'TRANSLATED', 'ثلاث ماكينات، خياطان، وأربعون قطعة أسبوعيًا. أكثر تعديل مطلوب ليس ما تتوقعه.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400056, now(), now(), 'seed', '<p>Behind the Olaya store is a room with three machines, where two tailors alter about forty garments a week.</p><h2>The most requested change</h2><p>Not shortening trousers — taking in the shoulder. Most shirts are cut for a broader shoulder than average here, and a centimetre and a half changes the whole line of the piece.</p><h2>Why it is free</h2><p>Because an altered garment does not come back as a return, and because someone wearing something that actually fits comes back to buy again. The arithmetic is simple.</p><h2>What cannot be altered</h2><ul><li>Letting out a narrow shoulder — the cloth is not there</li><li>Moving pockets without leaving a visible mark</li><li>Lined jackets, except at a cost beyond the garment''s worth</li></ul><h2>Three days</h2><p>Three days is standard. A piece needed for an occasion can usually be done in one, at no extra charge.</p>', 'Inside the alterations room', 'Inside the alterations room', 'A visit to the alterations room behind the Olaya store, and the changes people ask for most.', 'تعديل, خياطة, atelier', 'Inside the alterations room | The Magazine', 'inside-the-alterations-room', 'en', -40028, 'TRANSLATED', 'Three machines, two tailors, forty garments a week. The most requested alteration is not the one you would guess.', null, null, null)
on conflict (description_id) do nothing;
