-- post: building-a-capsule-wardrobe (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40029, now(), now(), 'seed', 'building-a-capsule-wardrobe', 'POST', 3, true, '65f023632bc46470c104b76f', 'PUBLISHED', now() - interval '28 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -490006, "categoryIds": [-451], "tags": ["خزانة", "أساسيات", "capsule"], "authorName": "سارة الدوسري", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400057, now(), now(), 'seed', '<h2>القاعدة الوحيدة</h2><p>كل قطعة يجب أن تتناسب مع ثلاث قطع أخرى على الأقل. القطعة التي لا تتناسب إلا مع واحدة تعيش في الخزانة ولا تخرج منها.</p><h2>القائمة</h2><ul><li>قميصان كتان محايدان</li><li>قميص أبيض قطني مُمشَّط</li><li>بنطالان: أحدهما فضفاض والآخر مستقيم</li><li>ثوب أو فستان بقَصّة بسيطة</li><li>طبقة خفيفة للأماكن المكيَّفة</li><li>حذاءان: يومي ورسمي</li><li>حزام، وحقيبة، ومنديل رقبة</li></ul><h2>لماذا تنجح</h2><p>لأن اللون المحايد يتناسب مع نفسه. أضف اللون في قطعة أو اثنتين لا في الاثنتي عشرة.</p><h2>ما تشتريه لاحقًا</h2><p>بعد شهر ستعرف أي قطعة تلبسها ثلاث مرات أسبوعيًا. اشترِ ثانية منها، لا شيئًا مختلفًا.</p>', 'خزانة من اثنتي عشرة قطعة', 'خزانة من اثنتي عشرة قطعة', 'كيف تبني خزانة مصغّرة تعمل في مناخ الرياض بين الخارج الحار والداخل المكيَّف.', 'خزانة, أساسيات, capsule', 'خزانة من اثنتي عشرة قطعة | المجلة', 'building-a-capsule-wardrobe-ar', 'ar', -40029, 'TRANSLATED', 'ليست تقشفًا، بل تقليل القرارات. اثنتا عشرة قطعة تعطي أكثر من ثلاثين إطلالة.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400058, now(), now(), 'seed', '<h2>The only rule</h2><p>Every piece must work with at least three others. A piece that works with one lives in the wardrobe and never leaves it.</p><h2>The list</h2><ul><li>Two neutral linen shirts</li><li>One white combed-cotton shirt</li><li>Two pairs of trousers: one wide, one straight</li><li>A thobe or dress with a simple line</li><li>A light layer for air-conditioned rooms</li><li>Two pairs of shoes: everyday and formal</li><li>A belt, a bag, a scarf</li></ul><h2>Why it works</h2><p>Because neutrals go with themselves. Put the colour in one or two pieces, not in all twelve.</p><h2>What to buy next</h2><p>After a month you will know which piece you wear three times a week. Buy a second one of that, not something different.</p>', 'A twelve-piece wardrobe', 'A twelve-piece wardrobe', 'How to build a capsule wardrobe that works in Riyadh, between the heat outside and the air conditioning inside.', 'خزانة, أساسيات, capsule', 'A twelve-piece wardrobe | The Magazine', 'building-a-capsule-wardrobe', 'en', -40029, 'TRANSLATED', 'Not austerity — fewer decisions. Twelve pieces yield more than thirty outfits.', null, null, null)
on conflict (description_id) do nothing;
