INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400059, now(), now(), 'seed', '<p>الاسترجاع المجاني يعني عددًا أكبر من المرتجعات. السؤال الذي يهم: أين تذهب؟</p><h2>الفحص</h2><p>كل قطعة تُفحص عند الوصول: البطاقة، الروائح، آثار الاستخدام، اكتمال الأزرار. الفحص يستغرق دقيقتين.</p><h2>الكي وإعادة التغليف</h2><p>94% تُكوى وتُعاد إلى الرف خلال 48 ساعة. هذه ليست نسبة تسويقية بل رقم المستودع لعام كامل.</p><h2>الباقي</h2><ul><li>القطع ذات عيب بسيط تُباع بخصم في ركن « الفرصة الثانية » بمعرض العليا</li><li>ما لا يصلح للبيع يُتبرَّع به لجمعية إكساء</li><li>لا نُتلف قطعًا صالحة للارتداء — لا في المستودع ولا خارجه</li></ul>', 'ماذا يحدث للقطع المرتجعة؟', 'ماذا يحدث للقطع المرتجعة؟', 'مسار القطعة المرتجعة من المستودع إلى الرف مجددًا، ولماذا لا نتلف شيئًا.', 'مرتجعات, استدامة, returns', 'ماذا يحدث للقطع المرتجعة؟ | المجلة', 'what-happens-to-returns-ar', 'ar', -40030, 'TRANSLATED', '94% تعود للبيع. الباقي لا يُتلَف، وهذا ما يجري له فعلًا.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400060, now(), now(), 'seed', '<p>Free returns mean more returns. The question that matters is where they go.</p><h2>Inspection</h2><p>Every piece is checked on arrival: tag, odour, signs of wear, buttons intact. It takes two minutes.</p><h2>Pressing and repacking</h2><p>94% are pressed and back on the rail within 48 hours. That is not a marketing figure; it is the warehouse number across a full year.</p><h2>The rest</h2><ul><li>Pieces with a minor flaw are sold at a discount in the “Second chance” corner of the Olaya store</li><li>Anything unsellable is donated to the Eksaa charity</li><li>We destroy nothing that can still be worn — not in the warehouse, not anywhere</li></ul>', 'What happens to returned pieces', 'What happens to returned pieces', 'The path a returned garment takes from the warehouse back to the rail, and why we destroy nothing.', 'مرتجعات, استدامة, returns', 'What happens to returned pieces | The Magazine', 'what-happens-to-returns', 'en', -40030, 'TRANSLATED', '94% go back on sale. Nothing is destroyed, and here is what actually happens to the rest.', null, null, null)
on conflict (description_id) do nothing;
