-- post: caring-for-linen (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40031, now(), now(), 'seed', 'caring-for-linen', 'POST', 5, true, '65f023632bc46470c104b76f', 'PUBLISHED', now() - interval '62 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -490003, "categoryIds": [-452, -451], "tags": ["كتان", "عناية", "linen"], "authorName": "خالد العتيبي", "featured": false}')
