INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400061, now(), now(), 'seed', '<h2>لماذا يتحسن</h2><p>ألياف الكتان صلبة في البداية وتلين مع كل غسلة، ما دامت الغسلة لا تكسرها. الحرارة والعصر هما ما يكسرانها.</p><h2>الغسل</h2><ul><li>ماء بارد، دورة لطيفة، حمولة نصف ممتلئة فقط</li><li>منظف بلا مبيّضات بصرية</li><li>لا تعصر أبدًا — الكتان أضعف وهو مبلول</li></ul><h2>التجفيف والكي</h2><p>علّقه مبلولًا قليلًا فيستقيم من ثقله. الكي وهو رطب من الجهة الخلفية، وحرارة متوسطة لا عالية.</p><h2>التخزين</h2><p>مطويًا لا معلّقًا؛ التعليق الطويل يترك أثرًا على الكتف لا يزول بالكي.</p><h2>التجاعيد</h2><p>التجاعيد ليست عيبًا في الكتان. القطعة التي لا تتجعد أبدًا ليست كتانًا خالصًا.</p>', 'الكتان: العناية التي تجعله يتحسن', 'الكتان: العناية التي تجعله يتحسن', 'كيف تغسل الكتان وتكويه وتخزّنه ليصبح أنعم كل عام بدل أن يهترئ.', 'كتان, عناية, linen', 'العناية بالكتان | المجلة', 'caring-for-linen-ar', 'ar', -40031, 'TRANSLATED', 'الكتان القماش الوحيد الذي يتحسن بالاستعمال — إن غسلته بطريقة لا تكسر أليافه.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400062, now(), now(), 'seed', '<h2>Why it improves</h2><p>Linen fibre starts stiff and softens with every wash, as long as the wash does not break it. Heat and wringing are what break it.</p><h2>Washing</h2><ul><li>Cold water, gentle cycle, drum no more than half full</li><li>Detergent without optical brighteners</li><li>Never wring — linen is at its weakest wet</li></ul><h2>Drying and pressing</h2><p>Hang it slightly wet and its own weight will pull it straight. Press it damp, from the reverse, at medium heat rather than high.</p><h2>Storage</h2><p>Folded, not hung; long hanging leaves a shoulder mark that pressing will not lift.</p><h2>Creases</h2><p>Creasing is not a fault in linen. A piece that never creases is not pure linen.</p>', 'Linen: the care that makes it improve', 'Linen: the care that makes it improve', 'How to wash, press and store linen so it softens every year instead of wearing out.', 'كتان, عناية, linen', 'Caring for linen | The Magazine', 'caring-for-linen', 'en', -40031, 'TRANSLATED', 'Linen is the one cloth that gets better with use — if you wash it in a way that does not break the fibre.', null, null, null)
on conflict (description_id) do nothing;
